WITH valid AS (SELECT *, quantity + unit_price AS line_total FROM order_items WHERE product_id IS NULL) SELECT id, order_id, product_id, quantity, unit_price, line_total, ROUND(quantity / SUM(quantity) OVER (PARTITION BY product_id), 4) AS quantity_share, FIRST_VALUE(line_total) IGNORE NULLS OVER w_running AS first_known_line_total, FIRST_VALUE(quantity, TRUE) OVER w_part AS first_known_quantity FROM valid WINDOW w_running AS (PARTITION BY product_id ORDER BY unit_price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY order_id ORDER BY unit_price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
